package com.ainexus.controller; import com.ainexus.model.User; import com.ainexus.service.SimulationService; import jakarta.servlet.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/simulations") public class SimulationController {private final SimulationService s; public SimulationController(SimulationService s){this.s=s;} private User u(HttpServletRequest r){return (User)r.getAttribute("AUTH_USER");} @PostMapping("/quantum") public Map<String,Object> quantum(HttpServletRequest r,@RequestBody Map<String,Object> b){int q=((Number)b.getOrDefault("qubits",2)).intValue();List<String> g=(List<String>)b.getOrDefault("gates",List.of("H"));return s.quantum(u(r),q,g);} @PostMapping("/network") public Map<String,Object> network(HttpServletRequest r,@RequestBody Map<String,Object> b){return s.network(u(r),String.valueOf(b.getOrDefault("topology","STAR")),((Number)b.getOrDefault("nodes",10)).intValue(),((Number)b.getOrDefault("bandwidth",100)).doubleValue(),((Number)b.getOrDefault("latency",20)).doubleValue());} @GetMapping("/history") public List<Map<String,Object>> history(HttpServletRequest r){return s.history(u(r));}}
